// 👉 EDITE ESTA LISTA — cada fonte é um feed RSS.
// Google News: troque/adicione buscas na função gnews(). "when:7d" = últimos 7 dias.
// Google Alertas: google.com/alerts → crie o alerta → "Mostrar opções" →
//   "Enviar para: Feed RSS" → copie o link do ícone RSS e cole abaixo.

const gnews = (q) =>
  `https://news.google.com/rss/search?q=${encodeURIComponent(q)}&hl=pt-BR&gl=BR&ceid=BR:pt-419`;

const fontes = [
  // ── Eventos (Recife primeiro) ──
  { nome: 'GNews: eventos tech Recife',      url: gnews('evento tecnologia (Recife OR Pernambuco) when:7d') },
  { nome: 'GNews: Porto Digital',            url: gnews('"Porto Digital" evento when:7d') },
  { nome: 'GNews: eventos de ES',            url: gnews('"engenharia de software" (evento OR congresso OR meetup) when:7d') },

  // ── Hackathons & competições ──
  { nome: 'GNews: hackathon PE',             url: gnews('hackathon (Recife OR Pernambuco OR Nordeste) when:7d') },
  { nome: 'GNews: hackathon inscrições',     url: gnews('hackathon inscrições abertas when:7d') },
  { nome: 'GNews: maratona de programação',  url: gnews('"maratona de programação" when:7d') },

  // ── Temas polêmicos / debates ──
  { nome: 'GNews: IA e programadores',       url: gnews('("vibe coding" OR "IA" programadores OR desenvolvedores) polêmica when:7d') },
  { nome: 'Hacker News: software engineering', url: 'https://hnrss.org/newest?q=%22software+engineering%22&points=100' },
  { nome: 'Hacker News: AI coding',          url: 'https://hnrss.org/newest?q=AI+coding&points=150' },
  { nome: 'Lobsters: practices',             url: 'https://lobste.rs/t/practices.rss' },
  { nome: 'The Pragmatic Engineer',          url: 'https://newsletter.pragmaticengineer.com/feed' },
  { nome: 'Reddit: r/ExperiencedDevs',       url: 'https://www.reddit.com/r/ExperiencedDevs/top/.rss?t=week' },

  // ── Seus Google Alertas (descomente e cole os links) ──
  // { nome: 'Alerta: hackathon Recife', url: 'https://www.google.com/alerts/feeds/XXXX/YYYY' },
  // { nome: 'Alerta: CIn UFPE evento',  url: 'https://www.google.com/alerts/feeds/XXXX/ZZZZ' },
];

return fontes.map(f => ({ json: f }));

// Junta tudo, remove duplicados e o que já foi enviado, filtra últimos 7 dias
// e monta UM texto com todos os itens para a IA.

const DIAS = 7;            // janela de tempo
const MAX_POR_FONTE = 12;  // evita que uma fonte domine a edição
const MAX_TOTAL = 70;      // limite de itens enviados para a IA

const agora = Date.now();
const limite = agora - DIAS * 864e5;

// Memória de links já enviados (só persiste em execuções do workflow ATIVO,
// não em testes manuais). Itens somem da memória após 60 dias.
const memoria = $getWorkflowStaticData('global');
memoria.enviados = memoria.enviados || {};
for (const [k, t] of Object.entries(memoria.enviados)) {
  if (agora - t > 60 * 864e5) delete memoria.enviados[k];
}

// Google Alertas embrulham o link real em google.com/url?url=...
function limparLink(link) {
  try {
    const u = new URL(link);
    if (u.hostname.includes('google.') && u.pathname === '/url') {
      return u.searchParams.get('url') || link;
    }
  } catch (e) {}
  return link;
}

function limparTexto(s) {
  return String(s || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

const chaveDe = (link) => link.split('#')[0].replace(/\/$/, '').toLowerCase();

const vistos = new Set();
const porFonte = {};
const fontesComErro = new Set();
const itens = [];

for (const { json } of $input.all()) {
  const fonte = json.fonte || 'desconhecida';
  if (json.error) { fontesComErro.add(fonte); continue; }
  if (!json.link || !json.title) continue;

  const link = limparLink(json.link);
  const chave = chaveDe(link);
  if (vistos.has(chave) || memoria.enviados[chave]) continue;

  const data = new Date(json.isoDate || json.pubDate || 0).getTime();
  if (!data || data < limite) continue;

  porFonte[fonte] = (porFonte[fonte] || 0) + 1;
  if (porFonte[fonte] > MAX_POR_FONTE) continue;

  vistos.add(chave);
  itens.push({
    chave,
    fonte,
    titulo: limparTexto(json.title),
    link,
    data: new Date(data).toISOString().slice(0, 10),
    resumo: limparTexto(json.contentSnippet || json.content || json.summary).slice(0, 400),
  });
}

itens.sort((a, b) => b.data.localeCompare(a.data));
const selecionados = itens.slice(0, MAX_TOTAL);
for (const i of selecionados) memoria.enviados[i.chave] = agora;

const lista = selecionados.map((i, n) =>
  `[${n + 1}] ${i.titulo}\nFonte: ${i.fonte} | Data: ${i.data}\nResumo: ${i.resumo || '(sem resumo)'}\nLink: ${i.link}`
).join('\n\n');

const hoje = new Date().toLocaleDateString('pt-BR', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
  timeZone: 'America/Recife',
});

return [{
  json: {
    hoje,
    quantidade: selecionados.length,
    lista: lista || '(nenhum item novo nesta semana)',
    fontesComErro: [...fontesComErro],
  },
}];

// Limpa a resposta da IA e monta assunto + corpo do e-mail.
let html = String($input.first().json.text || '')
  .replace(/^\s*```(?:html)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

const info = $('Filtrar e preparar itens').first().json;
if (info.fontesComErro && info.fontesComErro.length) {
  html += `<p style="max-width:600px;margin:24px auto 0;font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#888">` +
          `⚠️ Fontes que falharam nesta semana: ${info.fontesComErro.join(', ')}</p>`;
}

const data = new Date().toLocaleDateString('pt-BR', {
  day: '2-digit', month: '2-digit', timeZone: 'America/Recife',
});

return [{ json: { assunto: `☕ the SE news — ${data}`, html } }];
